public record Coordenada(double lat, double lon) implements Comparable<Coordenada> {
    // Campo estatico
    public static final Coordenada ORIGEN = new Coordenada(0, 0);

    // Metodo adicional
    public double distancia(Coordenada otra) {
        return Math.sqrt(Math.pow(lat - otra.lat, 2) + Math.pow(lon - otra.lon, 2));
    }

    // Implementacion de interfaz
    @Override
    public int compareTo(Coordenada otra) {
        return Double.compare(this.lat, otra.lat);
    }

    // Canonical constructor personalizado
    public Coordenada {
        if (lat < -90 || lat > 90) throw new IllegalArgumentException("Latitud invalida");
        if (lon < -180 || lon > 180) throw new IllegalArgumentException("Longitud invalida");
    }
}

// Sealed class con permisos
public sealed class Forma permits Circulo, Rectangulo, Triangulo { }

public final class Circulo extends Forma {
    double radio;
}

public final class Rectangulo extends Forma {
    double ancho, alto;
}

public non-sealed class Triangulo extends Forma { }

// El compilador sabe que solo hay 3 casos
String describir(Forma forma) {
    return switch (forma) {
        case Circulo c    -> "Circulo de radio " + c.radio;
        case Rectangulo r -> "Rectangulo " + r.ancho + "x" + r.alto;
        case Triangulo t  -> "Triangulo";
        // No se necesita default: el compilador verifica exhaustividad
    };
}

// Algebraic data type con records y sealed classes
public sealed interface Resultado permits Exito, Error, Cargando { }
public record Exito(String datos) implements Resultado { }
public record Error(String mensaje) implements Resultado { }
public record Cargando() implements Resultado { }

// Pattern matching exhaustivo
String procesar(Resultado r) {
    return switch (r) {
        case Exito e  -> "OK: " + e.datos();
        case Error e  -> "Fallo: " + e.mensaje();
        case Cargando -> "Cargando...";
        // No default necesario: sealed class tiene 3 casos, todos cubiertos
    };
}

// Java 21: pattern matching con guarded patterns
if (r instanceof Exito(String datos) && datos.length() > 5) {
    System.out.println("Exito largo: " + datos);
}

